package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct string // PIC X(4) @0 len=4
	ScPrin decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64 // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsBal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsYear int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsBalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec SchedRec
var records []string
var recIdx int
var inputDone bool

func normalizeBal(d decimal.Decimal) decimal.Decimal {
	// keep low-order digits that fit in PIC 9(8)V99 : 10 digits of cents
	total := d.Shift(2).IntPart() // cents
	const mod int64 = 10000000000 // 10^10
	rem := total % mod
	if rem < 0 {
		rem += mod
	}
	return decimal.New(rem, -2)
}

func formatBalEd(v decimal.Decimal) string {
	// v is assumed already normalized to scale 2 and non-negative
	if v.IsNegative() {
		v = v.Neg()
	}
	// total cents modulo 10^10 for overflow drop
	total := v.Shift(2).IntPart()
	const mod int64 = 10000000000
	rem := total % mod
	if rem < 0 {
		rem += mod
	}
	if rem < 0 {
		rem = 0
	}
	intPart := rem / 100
	fracPart := rem % 100
	intStr := fmt.Sprintf("%08d", intPart)
	fracStr := fmt.Sprintf("%02d", fracPart)

	const intSlots = 8
	// first non-zero position
	firstNonZero := intSlots // means all zero
	for i := 0; i < intSlots; i++ {
		if intStr[i] != '0' {
			firstNonZero = i
			break
		}
	}
	picture := "ZZ,ZZZ,ZZ9.99"
	// picture length 13
	res := make([]byte, len(picture))
	intSlotIdx := 0
	fracIdx := 0
	// digits before each position: count of int slots consumed
	for pi := 0; pi < len(picture); pi++ {
		ch := picture[pi]
		switch ch {
		case 'Z':
			digit := intStr[intSlotIdx]
			intSlotIdx++
			if intSlotIdx-1 < firstNonZero {
				res[pi] = ' '
			} else {
				res[pi] = digit
			}
		case '9':
			// determine if before or after dot
			if pi < 10 { // integer part 9
				digit := intStr[intSlotIdx]
				intSlotIdx++
				res[pi] = digit
			} else {
				// fractional
				res[pi] = fracStr[fracIdx]
				fracIdx++
			}
		case ',':
			// comma in integer part
			digitSlotsBefore := intSlotIdx
			if firstNonZero < digitSlotsBefore {
				res[pi] = ','
			} else {
				res[pi] = ' '
			}
		case '.':
			res[pi] = '.'
		default:
			res[pi] = byte(ch)
		}
	}
	return string(res)
}

func formatPIC99(v int64) string {
	// zero-padded to 2 digits, low-order digits kept
	// PIC 99 overflow: keep low 2 digits
	mv := v % 100
	if mv < 0 {
		mv += 100
	}
	return fmt.Sprintf("%02d", mv)
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains only digits, may have leading zeros
	// Remove non-digit? Assume digits
	// Parse as integer
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback: filter digits
		filtered := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered == "" {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(filtered)
	}
	return d.Shift(-scale)
}

func loadRecords() {
	f, err := os.Open("input.dat")
	if err != nil {
		// no file => no records
		records = []string{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// scanner strips newline, but keeps other chars
		// Pad/truncate to 16
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		records = append(records, line)
	}
}

func READ_PARA() {
	if recIdx >= len(records) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := records[recIdx]
	recIdx++
	// parse fields
	// SC-ACCT 0:4
	curRec.ScAcct = line[0:4]
	// SC-PRIN 4:11 (7)
	prinStr := line[4:11]
	curRec.ScPrin = parseDecimalDigits(prinStr, 2)
	// SC-RATE 11:15 (4)
	rateStr := line[11:15]
	curRec.ScRate = parseDecimalDigits(rateStr, 2)
	// SC-YEARS 15:16 (1)
	yearStr := line[15:16]
	yearStrTrim := strings.TrimSpace(yearStr)
	if yearStrTrim == "" {
		curRec.ScYears = 0
	} else {
		var v int64
		_, err := fmt.Sscanf(yearStrTrim, "%d", &v)
		if err != nil {
			v = 0
			// manual parse digit
			for _, ch := range yearStrTrim {
				if ch >= '0' && ch <= '9' {
					v = v*10 + int64(ch-'0')
				}
			}
		}
		curRec.ScYears = v
	}
	inputDone = false
	WsEofFlag = "N"
}

func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = curRec.ScPrin
	// normalize to PIC 9(8)V99 (truncate high order if needed)
	WsBal = normalizeBal(WsBal)

	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > curRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		factor := decimal.NewFromInt(1).Add(curRec.ScRate.Shift(-2))
		WsBal = WsBal.Mul(factor).Round(2)
		WsBal = normalizeBal(WsBal)
		WsBalEd = formatBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		// WS-YEAR is PIC 99 zero-padded
		fmt.Printf("%s Y%s %s\n", curRec.ScAcct, formatPIC99(WsYear), WsBalEd)
		WsYear++
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount++
	// keep only low-order 2 digits for PIC 99 overflow semantics
	WsCount = WsCount % 100
	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT SCHED-FILE
	loadRecords()
	recIdx = 0
	inputDone = false
	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0
	WsBalEd = ""

	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE SCHED-FILE
	fmt.Printf("SCHEDULES: %s\n", formatPIC99(WsCount))
}

func main() {
	MAIN_PARA()
}
